CREATE TABLE hosts (id serial PRIMARY KEY, name text, rack int);
INSERT INTO hosts(name, rack)
  SELECT 'rack' || (g % 50) || '-node' || g, g % 50 FROM generate_series(1, 5000) g;
CREATE INDEX ON hosts USING gin (rack, name);
